var largestInteger = function(nums, k) {
    const freq = new Map();

    for (const num of nums) {
        freq.set(num, (freq.get(num) || 0) + 1);
    }

    const first = nums[0];
    const last = nums[nums.length - 1];
    let res = -1;

    for (const [num, count] of freq) {
        if (k === 1 || num === first || num === last) {
            if (count === 1 && num > res) {
                res = num;
            }
        }
    }

    return res;
};

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var largestInteger = function(nums, k) {
    const n = nums.length;

    if (k === n) {
        return Math.max(...nums);
    }

    const freq = new Map();

    for (const num of nums) {
        freq.set(num, (freq.get(num) || 0) + 1);
    }

    if (k === 1) {
        return Math.max(-1, ...nums.filter(num => freq.get(num) === 1));
    }

    const first = nums[0];
    const firstC = freq.get(first);
    const last = nums[n - 1];
    const lastC = freq.get(last);

    if (firstC === 1 && lastC === 1) return Math.max(first, last);
    if (firstC === 1) return first;
    if (lastC === 1) return last;
    return -1;
};
